const byName=new Map(catalog.map(t=>[t.name,t]));
const get=name=>byName.get(name)||null;
const DEFAULTS={melee:2,attack:4,heal:8,support:12,range:7,supportDuration:4,dropChance:.1};
const roll=(lo,hi,rnd)=>Math.floor(lo+(hi-lo+1)*Math.min(.999999,Math.max(0,rnd())));
function hits(a,m,q){const dx=q.x-m.x,dy=q.y-m.y,d=Math.max(Math.abs(dx),Math.abs(dy));
 if(a.shape==='melee')return d<=1;
 if(d>DEFAULTS.range)return false;
 if(a.shape==='wave'){const dir=m._aim||[Math.sign(dx),Math.sign(dy)];return dx*dir[0]+dy*dir[1]>0&&Math.abs(dx*dir[1]-dy*dir[0])<=Math.max(1,d*.5)}
 if(a.shape==='area'&&a.name==='Twist Rage')return d<=2;
 return true;
}
// Runtime clocks are transient on each monster, never character save data.
function tick(m,dt,engaged,host,rnd=Math.random){if(!m.t.official)return [];
 const A=m.t.abilities;m._abilityCd??=A.map((a,i)=>a.shape==='melee'?1:1+i*.45);
 const events=[];for(let i=0;i<A.length;i++){const a=A[i];m._abilityCd[i]-=dt;if(m._abilityCd[i]>0)continue;
 if(!engaged){m._abilityCd[i]=.2;continue}
 if(a.kind!=='attack'&&!host)continue;
 if(a.kind==='heal'&&m.hp>=m.t.hp)continue;
 m._abilityCd[i]=a.shape==='melee'?DEFAULTS.melee:a.kind==='attack'?DEFAULTS.attack:a.kind==='heal'?DEFAULTS.heal:DEFAULTS.support;
 events.push({...a,damage:a.min==null?0:roll(a.min,a.max,rnd)});
 }return events;
}
// Support abilities change only transient monster fields (never saves); invisible monsters are hidden from drawing and targeting.
function support(m,a,now=Date.now()){if(a.kind==='heal'){m.hp=Math.min(m.t.hp,m.hp+(a.damage||0));return true}
 if(a.kind==='haste'){m.hasteUntil=now+DEFAULTS.supportDuration*1000;return true}
 if(a.kind==='invisible'){m.invisibleUntil=now+DEFAULTS.supportDuration*1000;return true}return false}
const hidden=(m,now=Date.now())=>!!m&&(m.invisibleUntil||0)>now;
function mitigate(raw,el,shield,armor,resist,stance,taken){if(raw<=0)return 0;
 const defense=el==='phys'?Math.max(0,shield)*.25+Math.max(0,armor):0;
 return taken(stance(resist(Math.max(0,Math.round(raw-defense)),el)));
}
function lineClear(m,q,pass){let x=m.x,y=m.y;const dx=Math.abs(q.x-x),dy=Math.abs(q.y-y),sx=x<q.x?1:-1,sy=y<q.y?1:-1;let err=dx-dy;
 while(x!==q.x||y!==q.y){const e=2*err;if(e>-dy){err-=dy;x+=sx}if(e<dx){err+=dx;y+=sy}if((x!==q.x||y!==q.y)&&!pass(x,y))return false}return true;
}
// Stable difficulty pools, in original zone order; no map coordinates or legacy zone indices change.
function populate(zones){const sorted=[...catalog].sort((a,b)=>a.hp-b.hp||a.name.localeCompare(b.name));
 sorted.forEach((t,i)=>{const zi=Math.min(7,Math.floor(i*8/sorted.length)),z=i%2,Z=zones[zi];if(!Z)return;
 const key=z?'wikiSub':'wikiTop';Z[key]??=[];Z[key].push(t.name)});
}
function species(Z,z,rnd=Math.random){const pool=[z?Z.sub:Z.top,...(z?Z.wikiSub:Z.wikiTop)||[]];return pool[Math.min(pool.length-1,Math.floor(rnd()*pool.length))]}
function loot(t,rnd=Math.random){if(!t.official)return null;const out=[];
 for(const a of t.drops){if(a.name==='Gold'||a.name==='Platinum'||rnd()<DEFAULTS.dropChance)out.push({name:a.name,n:roll(a.min,a.max,rnd)})}return out;
}
function atlasSprite(t,image,doc){const [x,y,w,h]=t.sprite,c=doc.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(image,x,y,w,h,0,0,w,h);c.complete=true;c.naturalWidth=w;c.naturalHeight=h;return c}
root.LawlMonsters={catalog,get,ATLAS,DEFAULTS,hits,tick,support,hidden,mitigate,lineClear,populate,species,loot,atlasSprite,COUNT:169};
